const slots = $slots;
probe(Array.isArray(slots.members) && slots.members.length > 0, "the statement must name at least one group");
probe(Number.isInteger(slots.threshold) && slots.threshold > 0, "the threshold must be a positive whole number");
const total = slots.members.reduce((sum, member) => sum + member.seats, 0);
probe(total >= slots.threshold, "the stated seats must add up to a number that meets the threshold");
const winning = slots.members.filter((member) => member.seats >= slots.threshold);
const losing = slots.members.filter((member) => member.seats < slots.threshold);
probe(winning.length > 0 && losing.length > 0, "the stated seats must leave at least one group below the threshold");
const coalitions = [];
for (let start = 0; start < winning.length; start += 1) {
  for (let end = start + 1; end < winning.length; end += 1) {
    const subset = winning.slice(start, end + 1);
    const seatSum = subset.reduce((sum, member) => sum + member.seats, 0);
    if (seatSum < slots.threshold) {
      continue;
    }
    const lose = losing.find((member) => member.seats === subset.reduce((sum, other) => sum + other.seats, 0));
    if (lose !== undefined) {
      if (lose.seats === subset.reduce((sum, other) => sum + other.seats, 0)) {
        continue;
      }
      const loseIndex = subset.indexOf(lose);
      if (loseIndex !== -1 && subset.slice(0, loseIndex).reduce((sum, other) => sum + other.seats, 0) === seatSum) {
        continue;
      }
    }
    coalitions.push({ names: subset.map((member) => member.name), seats: seatSum });
  }
}
probe(coalitions.length > 0, "some combination of winning members must reach the threshold");
const chosen = coalitions.slice(0, 1).sort((left, right) => right.seats - left.seats)[0];
probe(chosen.seats >= slots.threshold, "the chosen coalition must reach the threshold");
const losingMembers = coalitions.filter((candidate) => candidate.seats < slots.threshold).map((candidate) => candidate.names.join(", "));
probe(losingMembers.length > 0, "the chosen coalition must leave at least one member below the threshold");
return "One minimal winning coalition is " + chosen.names.join(" and ") + ", with " + chosen.seats + " seats. Any larger coalition will lose if any member is removed.";
